:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0e0;
  --red: #e74c3c;
  --amber: #f1c40f;
  --green: #2ecc71;
  --inactive: #3a3a50;
  --button-bg: #3a3a50;
  --button-hover: #4a4a60;
  --button-active: #5a5a70;
  --focus: #f1c40f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 360px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 24px;
  margin-bottom: 24px;
  font-weight: 600;
}

.traffic-light {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.lamp {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--inactive);
  transition: background 0.2s, box-shadow 0.2s;
}

.lamp.red.active {
  background: var(--red);
  box-shadow: 0 0 24px var(--red);
}

.lamp.amber.active {
  background: var(--amber);
  box-shadow: 0 0 24px var(--amber);
}

.lamp.green.active {
  background: var(--green);
  box-shadow: 0 0 24px var(--green);
}

.status {
  font-size: 20px;
  font-weight: 500;
  margin-bottom: 24px;
  min-height: 1.5em;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 18px;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: var(--button-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: var(--button-hover);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active {
  background: var(--button-active);
  transform: scale(0.97);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  .lamp {
    width: 64px;
    height: 64px;
  }
  button {
    font-size: 16px;
    padding: 10px 18px;
  }
}

const redLamp = document.getElementById('red-lamp');
const amberLamp = document.getElementById('amber-lamp');
const greenLamp = document.getElementById('green-lamp');
const statusLabel = document.getElementById('status-label');
const startBtn = document.getElementById('start-btn');
const stopBtn = document.getElementById('stop-btn');

const SEQUENCE = [
  { color: 'red', duration: 3000, label: 'Red' },
  { color: 'green', duration: 3000, label: 'Green' },
  { color: 'amber', duration: 1000, label: 'Amber' },
];

let currentIndex = -1;
let timerId = null;
let running = false;

function clearLamps() {
  redLamp.classList.remove('active');
  amberLamp.classList.remove('active');
  greenLamp.classList.remove('active');
}

function setLamp(color) {
  clearLamps();
  if (color === 'red') redLamp.classList.add('active');
  else if (color === 'amber') amberLamp.classList.add('active');
  else if (color === 'green') greenLamp.classList.add('active');
}

function nextState() {
  if (!running) return;
  currentIndex = (currentIndex + 1) % SEQUENCE.length;
  const state = SEQUENCE[currentIndex];
  setLamp(state.color);
  statusLabel.textContent = state.label;
  timerId = setTimeout(nextState, state.duration);
}

function start() {
  if (running) return;
  running = true;
  currentIndex = -1;
  startBtn.disabled = true;
  stopBtn.disabled = false;
  nextState();
}

function stop() {
  if (!running) return;
  running = false;
  clearTimeout(timerId);
  timerId = null;
  clearLamps();
  statusLabel.textContent = 'Stopped';
  startBtn.disabled = false;
  stopBtn.disabled = true;
}

startBtn.addEventListener('click', start);
stopBtn.addEventListener('click', stop);

// Initial state
stopBtn.disabled = true;
statusLabel.textContent = 'Stopped';
